<?php
require_once __DIR__ . "/../facility_photos.php";
function page_map(): void {
 heading('SITUATIONAL AWARENESS','Situation map','Find verified incidents, hospitals and shelters across Sri Lanka. Pending and rejected reports are not shown publicly.');
 echo '<div class="map-toolbar"><label>District <select id="map-district"><option value="">All 25 districts</option>';foreach(districts() as $district)echo '<option>'.e($district).'</option>';echo '</select></label><label>Category <select id="map-type"><option value="">All disaster categories</option>';foreach(types() as $t)echo '<option>'.e($t['name']).'</option>';echo '</select></label><label>Severity <select id="map-severity"><option value="">All severities</option><option>Low</option><option>Medium</option><option>High</option><option>Critical</option></select></label><label>Status <select id="map-status"><option value="verified">Verified active</option><option value="resolved">Resolved</option><option value="">All public incidents</option></select></label><label class="check"><input id="map-facilities" type="checkbox" checked> Show facilities</label></div><div class="map-layout"><div><div id="situation-map" class="map" aria-label="Interactive disaster and facility map"></div><div id="map-status-message" class="hint" role="status">Loading map records…</div><div class="map-legend"><span><i class="legend-dot critical"></i>Critical</span><span><i class="legend-dot high"></i>High</span><span><i class="legend-dot medium"></i>Medium</span><span><i class="legend-dot low"></i>Low</span><span><i class="legend-dot facility"></i>Facility</span></div><p class="hint">Map tiles © OpenStreetMap contributors. Internet is required for the street basemap; markers and the record list remain available without tiles.</p></div><section class="card padded"><h2>Visible records</h2><div id="map-records" class="map-records"></div></section></div>';
}
function page_facilities(): void {
 $district=(string)($_GET['district']??'');if(!in_array($district,districts(),true))$district='';$q=trim((string)($_GET['q']??''));$kind=(string)($_GET['kind']??'');$status=(string)($_GET['status']??'');$lat=filter_var($_GET['lat']??null,FILTER_VALIDATE_FLOAT);$lng=filter_var($_GET['lng']??null,FILTER_VALIDATE_FLOAT);$near=$lat!==false&&$lat!==null&&$lng!==false&&$lng!==null&&$lat>=5.5&&$lat<=10.2&&$lng>=79&&$lng<=82.5;
 heading('SAFE PLACES','Shelters & hospitals','Find hospitals in all 25 districts and view shelter records. Confirm hospital availability before travelling. Fictional facilities are marked as examples.');echo '<form class="filters" method="get"><input type="hidden" name="page" value="facilities">';field('q','Name, area or services','search',$q,false);select('district','District',[''=>'All 25 districts']+array_combine(districts(),districts()),$district);select('kind','Facility type',[''=>'All facilities','shelter'=>'Shelters','hospital'=>'Hospitals'],$kind);select('status','Operational status',[''=>'All statuses','open'=>'Open','limited'=>'Limited','closed'=>'Closed']+((scalar("SELECT COUNT(*) FROM facilities WHERE status='unknown'")||$status==='unknown')?['unknown'=>'Availability unverified']:[]),$status);field('lat','Your latitude (optional)','number',$near?$lat:'',false,'step="any" min="5.5" max="10.2"');field('lng','Your longitude (optional)','number',$near?$lng:'',false,'step="any" min="79" max="82.5"');echo '<button class="button secondary">Search</button></form>';
 echo '<p class="hint">Hospital location data: <a href="https://data.humdata.org/dataset/sri-lanka-healthsites">Healthsites</a> / © <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a>.</p>';
 $where=[];$params=[];if($district){$where[]='area=?';$params[]=$district;}if($q){$where[]='(name LIKE ? OR area LIKE ? OR services LIKE ?)';array_push($params,'%'.$q.'%','%'.$q.'%','%'.$q.'%');}if($kind){$where[]='kind=?';$params[]=$kind;}if($status){$where[]='status=?';$params[]=$status;}$rows=all('SELECT * FROM facilities'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY name',$params);if($near){foreach($rows as &$r)$r['distance']=distance((float)$lat,(float)$lng,(float)$r['latitude'],(float)$r['longitude']);unset($r);usort($rows,fn($a,$b)=>$a['distance']<=>$b['distance']);}
 echo '<div class="facility-grid">';if(!$rows)empty_state('No facilities found','Try changing your search filters.');foreach($rows as $r){echo '<article class="card facility-card">'.facility_photo($r).'<div class="padded"><h2>'.e($r['name']).'</h2><p class="muted">'.e($r['area']).($near?' · '.e(round($r['distance'],1)).' km away (straight line)':'').'</p><p>'.e($r['address']).'</p><p>'.e($r['services']).'</p>';if($r['capacity_known'])echo '<div class="facility-stats"><span><strong>'.e(max(0,(int)$r['capacity']-(int)$r['occupancy'])).'</strong> spaces available</span><span><strong>'.e($r['occupancy']).' / '.e($r['capacity']).'</strong> current occupancy</span></div><div class="capacity-track"><span style="width:'.min(100,$r['capacity']?round($r['occupancy']/$r['capacity']*100):0).'%"></span></div>';else echo '<p class="hint">Capacity and occupancy not recorded. Confirm current availability with the facility.</p>';echo '<p>Contact: '.e($r['phone']).'<br>'.($r['emergency_service']?'Emergency services available':'Emergency service availability not recorded').'</p><small>Record updated '.e($r['updated_at']).'</small><div class="form-actions"><a class="button secondary small" href="'.url('map',['facility'=>$r['id']]).'">View on map</a>';if(can('coordinate')||(can('facilities')&&(int)$r['manager_id']===(int)user()['id']))echo '<a class="button small" href="'.url('facilities',['edit'=>$r['id']]).'">Edit facility</a>';echo '</div></div></article>';}echo '</div>';
 if(can('facilities')){$id=(int)($_GET['edit']??0);$r=$id?one('SELECT * FROM facilities WHERE id=?',[$id]):null;$editable=can('coordinate')||($r&&(int)$r['manager_id']===(int)user()['id']);if($editable){if($id&&!$r)throw new RuntimeException('Facility not found.');$r=$r??[];start_form('facility',$id?'Update facility':'Add a facility');echo '<input type="hidden" name="id" value="'.$id.'"><div class="form-grid">';select('kind','Type',['shelter'=>'Shelter','hospital'=>'Hospital'],$r['kind']??'shelter');field('name','Facility name','text',$r['name']??'',true,'minlength="3" maxlength="150"');field('address','Address','text',$r['address']??'',true,'minlength="5" maxlength="255"');field('phone','Contact number','tel',$r['phone']??'',true,'maxlength="30"');field('capacity','Capacity','number',$r['capacity']??0,true,'min="0" max="1000000"');field('occupancy','Occupancy','number',$r['occupancy']??0,true,'min="0" max="1000000"');select('status','Operational status',['open'=>'Open','limited'=>'Limited','closed'=>'Closed','unknown'=>'Availability unverified'],$r['status']??'open');if(can('coordinate'))select('manager_id','Assigned facility manager',[0=>'Unassigned']+array_column(all("SELECT id,name FROM users WHERE role='facility_manager' AND active=1"),'name','id'),$r['manager_id']??0);echo '</div>';location_fields($r,true);echo '<label class="check"><input name="capacity_unknown" type="checkbox" '.(isset($r['capacity_known'])&&!$r['capacity_known']?'checked':'').'> Capacity and occupancy not yet confirmed</label>';textarea('services','Facilities and services',$r['services']??'',3,3000);echo '<label class="check"><input name="emergency_service" type="checkbox" '.(!empty($r['emergency_service'])?'checked':'').'> Emergency services available</label>';end_form('Save facility');}}
}
